// Port of src/lang.rs translate_locale / resolve_lang for the languages
// generated by scripts/gen-lang.mjs from src/lang/<lang>.rs.
import en from "./proto/lang_en.json";
import ru from "./proto/lang_ru.json";
import { localOptions } from "./config";

type Table = Record<string, string>;

const TABLES: Record<string, Table> = { en: en as Table, ru: ru as Table };

// get_langs: what the language selector offers
export const LANGS: [string, string][] = [
  ["en", "English"],
  ["ru", "Русский"],
];

// resolve_lang without the CJK fallback (no CJK tables are shipped)
export function resolveLang(saved: string, locale: string): string {
  let lang = saved.toLowerCase();
  if (lang === "default") lang = "";
  if (!lang) lang = (locale.toLowerCase().split("-")[0] ?? "").split("_")[0] ?? "";
  return lang;
}

// extract_placeholder: "There are {24} hours" -> ("There are {} hours", "24")
function extractPlaceholder(input: string): [string, string | null] {
  const m = /\{(.*?)\}/.exec(input);
  if (!m) return [input, null];
  return [input.replace(m[0], "{}"), m[1] ?? ""];
}

export function translate(locale: string, text: string, saved = localOptions.get("lang")): string {
  const lang = resolveLang(saved, locale || globalThis.navigator?.language || "");
  const [name, value] = extractPlaceholder(text);
  const fill = (s: string) => (value !== null ? s.replace("{}", () => value) : s);
  const v = (TABLES[lang] ?? TABLES.en!)[name];
  if (v) return fill(v);
  if (lang !== "en") {
    const e = TABLES.en![name];
    if (e) return fill(e);
  }
  return fill(name);
}
